describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 600 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: -100, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });

    it("accepts valid brackets", () => {
      expect(() => new WeightBasedShippingCalculator(brackets)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 for items with no weight", () => {
      const lines = [makeLine({}, 3)]; // no weightGrams
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects the first bracket (weight within lowest)", () => {
      // 250g total → bracket upToGrams=500 → 300 cents
      const lines = [makeLine({ weightGrams: 250 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // 500g exactly → bracket upToGrams=500 → 300 cents
      const lines = [makeLine({ weightGrams: 500 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects next bracket when just above boundary", () => {
      // 501g → bracket upToGrams=1000 → 600 cents
      const lines = [makeLine({ weightGrams: 501 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      // 5000g → bracket upToGrams=5000 → 1200 cents
      const lines = [makeLine({ weightGrams: 1000 }, 5)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses heaviest bracket cost as overflow default", () => {
      // 6000g → over all brackets, no overflowCostCents → last bracket cost (1200)
      const lines = [makeLine({ weightGrams: 2000 }, 3)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflowCostCents when specified", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [makeLine({ weightGrams: 2000 }, 3)]; // 6000g
      expect(calcWithOverflow.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("sums weight across multiple lines", () => {
      // 300*2 + 200*1 = 800g → bracket upToGrams=1000 → 600 cents
      const lines = [
        makeLine({ id: "a", weightGrams: 300 }, 2),
        makeLine({ id: "b", weightGrams: 200 }, 1),
      ];
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unordered: WeightBracket[] = [
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ];
      const calc2 = new WeightBasedShippingCalculator(unordered);
      const lines = [makeLine({ weightGrams: 400 }, 1)];
      expect(calc2.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

