  describe("snapshot", () => {
    it("returns deep copies of lines", () => {
      const cart = new Cart();
      const product = makeProduct({ id: "s1" });
      cart.add(product, 2);
      const snap = cart.snapshot();
      // mutate snapshot — should not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals – pricing pipeline", () => {
    it("computes subtotal from lines", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 500 }), 3); // 1500
      cart.add(makeProduct({ id: "b", unitPriceCents: 200 }), 2); // 400
      const t = cart.totals();
      expect(t.subtotalCents).toBe(1900);
    });

    it("returns zero totals for empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t.subtotalCents).toBe(0);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(0);
    });

    it("applies discount, then tax on discounted subtotal, then shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };

      const cart = new Cart({
        discountPolicy,
        taxCalculator,
        shippingCalculator,
        region: "US-CA",
      });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 2); // subtotal 2000

      const t = cart.totals();

      // discount called with subtotal
      expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(2000);
      // tax called with discounted subtotal (2000 - 200 = 1800)
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1800, "US-CA");
      // shipping called with lines and discounted subtotal
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        1800,
      );

      expect(t.subtotalCents).toBe(2000);
      expect(t.discountCents).toBe(200);
      expect(t.taxCents).toBe(80);
      expect(t.shippingCents).toBe(500);
      // total = discountedSubtotal + tax + shipping = 1800 + 80 + 500
      expect(t.totalCents).toBe(2380);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: () => 99999,
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(1000); // clamped to subtotal
      expect(t.totalCents).toBe(0); // all discounted, no tax, no shipping
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
