  });

  describe("checkout", () => {
    it("returns totals and lines without collaborators", async () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 500 }), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.product.id).toBe("a");
    });

    describe("price refresh", () => {
      it("refreshes prices before computing totals", async () => {
        const fetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(2000),
        };
        const cart = new Cart();
        cart.add(makeProduct({ id: "x", unitPriceCents: 1000 }), 1);
        const result = await cart.checkout({ priceFetcher: fetcher });
        expect(result.totals.subtotalCents).toBe(2000);
        expect(result.lines[0]!.product.unitPriceCents).toBe(2000);
        expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("x");
      });
    });

    describe("inventory check", () => {
      it("passes when items are available", async () => {
        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true }),
        };
        const cart = new Cart();
        cart.add(makeProduct({ id: "a" }), 2);
        const result = await cart.checkout({ inventoryChecker: checker });
        expect(result.totals.subtotalCents).toBe(2000);
        expect(checker.check).toHaveBeenCalledWith("a", 2);
      });

      it("throws InventoryError when item is unavailable", async () => {
        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: false,
            reason: "out of stock",
          }),
        };
        const cart = new Cart();
        cart.add(makeProduct({ id: "gone" }), 3);

        try {
          await cart.checkout({ inventoryChecker: checker });
          expect.unreachable("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("gone");
          expect(invErr.requested).toBe(3);
          expect(invErr.message).toBe("out of stock");
        }
      });

      it("throws InventoryError for partial-stock denial", async () => {
        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: true,
            availableQuantity: 1,
          }),
        };
        const cart = new Cart();
        cart.add(makeProduct({ id: "low" }), 5);

        try {
          await cart.checkout({ inventoryChecker: checker });
          expect.unreachable("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("low");
          expect(invErr.requested).toBe(5);
          expect(invErr.available).toBe(1);
        }
      });

      it("does not throw when availableQuantity meets requested", async () => {
        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: true,
            availableQuantity: 5,
          }),
        };
        const cart = new Cart();
        cart.add(makeProduct({ id: "ok" }), 5);
        const result = await cart.checkout({ inventoryChecker: checker });
        expect(result.totals.subtotalCents).toBe(5000);
      });
    });

    describe("async tax provider", () => {
      it("uses async tax provider to compute tax", async () => {
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.1),
        };
        const cart = new Cart({ region: "US" });
        cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
        const result = await cart.checkout({ asyncTaxProvider });
        // 10% of 1000 = 100
        expect(result.totals.taxCents).toBe(100);
        expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
      });

      it("applies discount before async tax calculation", async () => {
        const discountPolicy: DiscountPolicy = {
          computeDiscountCents: () => 200,
        };
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.1),
        };
        const cart = new Cart({ discountPolicy, region: "FR" });
        cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
        const result = await cart.checkout({ asyncTaxProvider });
        // discounted subtotal = 1000 - 200 = 800, tax = 10% of 800 = 80
        expect(result.totals.discountCents).toBe(200);
        expect(result.totals.taxCents).toBe(80);
      });

      it("propagates async tax provider failure", async () => {
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
        };
        const cart = new Cart();
        cart.add(makeProduct(), 1);
        await expect(
          cart.checkout({ asyncTaxProvider }),
        ).rejects.toThrow("tax service down");
      });
    });

    describe("full pipeline with all collaborators", () => {
      it("refreshes prices, checks inventory, applies async tax", async () => {
        const discountPolicy: DiscountPolicy = {
          computeDiscountCents: () => 100,
        };
        const shippingCalculator: ShippingCalculator = {
          computeShippingCents: () => 500,
        };
        const priceFetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(800),
        };
        const inventoryChecker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true }),
        };
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.05),
        };

        const cart = new Cart({ discountPolicy, shippingCalculator });
        cart.add(makeProduct({ id: "item1" }), 2);

        const result = await cart.checkout({
          priceFetcher,
          inventoryChecker,
          asyncTaxProvider,
        });

        // refreshed price: 800 * 2 = 1600 subtotal
        expect(result.totals.subtotalCents).toBe(1600);
        // discount: 100
        expect(result.totals.discountCents).toBe(100);
        // discounted subtotal: 1500, tax: 5% of 1500 = 75
        expect(result.totals.taxCents).toBe(75);
        // shipping: 500
        expect(result.totals.shippingCents).toBe(500);
        // total: 1500 + 75 + 500 = 2075
        expect(result.totals.totalCents).toBe(2075);

        expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("item1");
        expect(inventoryChecker.check).toHaveBeenCalledWith("item1", 2);
      });
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
  type DiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
      [-Infinity, "-Infinity"],
    ])("rejects %d (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts valid percent %d", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 as 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("floors fractional cents (10% of 1001 = 100, not 100.1)", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1001)).toBe(100);
    });

    it("100% discount equals the subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("handles large subtotal correctly", () => {
      const policy = new PercentageDiscountPolicy(15);
      // 15% of 1_000_000 = 150_000
      expect(policy.computeDiscountCents(1_000_000)).toBe(150_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });

    it("accepts positive integer", () => {
      expect(() => new FixedAmountDiscountPolicy(500)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns subtotal when fixed amount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });

    it("accepts a single policy", () => {
      expect(
        () => new CompositeDiscountPolicy([new NoDiscountPolicy()]),
      ).not.toThrow();
    });
  });

  describe("sum mode", () => {
    it("sums independent discounts from multiple policies", () => {
      const policies: DiscountPolicy[] = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100
        new FixedAmountDiscountPolicy(200), // fixed 200
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("each child receives the original subtotal, not remaining", () => {
      const policies: DiscountPolicy[] = [
        new FixedAmountDiscountPolicy(400),
        new FixedAmountDiscountPolicy(400),
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      // sum mode: 400 + 400 = 800 (both see 1000)
      expect(composite.computeDiscountCents(1000)).toBe(800);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy: DiscountPolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // -100 clamped to 0, + 300 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policies: DiscountPolicy[] = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
        new PercentageDiscountPolicy(10), // 10% of 900 = 90
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("second policy sees reduced subtotal", () => {
      const policies: DiscountPolicy[] = [
        new FixedAmountDiscountPolicy(600), // 600 off 1000, remaining 400
        new FixedAmountDiscountPolicy(600), // capped at 400 (remaining)
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      // total discount: 600 + 400 = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters in chain mode", () => {
      const big = new FixedAmountDiscountPolicy(500);
      const pct = new PercentageDiscountPolicy(50);

      const bigFirst = new CompositeDiscountPolicy([big, pct], "chain");
      const pctFirst = new CompositeDiscountPolicy([pct, big], "chain");

      // big first: 500 off 1000 → remaining 500, then 50% of 500 = 250 → total 750
      expect(bigFirst.computeDiscountCents(1000)).toBe(750);
      // pct first: 50% of 1000 = 500 off → remaining 500, then 500 off → total 1000
      expect(pctFirst.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy: DiscountPolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // negative clamped to 0, then 200 off 1000
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });

  describe("defaults to sum mode", () => {
    it("uses sum mode when no mode is specified", () => {
      const policies: DiscountPolicy[] = [
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ];
      const composite = new CompositeDiscountPolicy(policies);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine, Product } from "../src/product.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

function makeLine(
  product: Partial<Product> = {},
  quantity = 1,
): CartLine {
  return { product: makeProduct(product), quantity };
}

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "US"],
    [5000, "FR"],
    [-100, "US"],
  ])(
    "computeTaxCents(%i, %s) returns 0",
    (taxable, region) => {
      expect(calc.computeTaxCents(taxable, region)).toBe(0);
    },
  );
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative default rate", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects default rate > 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN default rate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects invalid region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": -0.05 }),
      ).toThrow(RangeError);
    });

    it("rejects region rate > 1", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 1.5 }),
      ).toThrow(RangeError);
    });

    it("accepts valid rates", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 0.08, "FR": 0.2 }, 0.1),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US": 0.08, "US-CA": 0.0875, "FR": 0.2 },
      0.05,
    );

    it("uses region-specific rate", () => {
      // 8% of 1000 = 80
      expect(calc.computeTaxCents(1000, "US")).toBe(80);
    });

    it("uses sub-region rate", () => {
      // 8.75% of 1000 = 87.5 → 87
      expect(calc.computeTaxCents(1000, "US-CA")).toBe(87);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 1000 = 50
      expect(calc.computeTaxCents(1000, "DE")).toBe(50);
    });

    it("floors fractional cents", () => {
      // 20% of 999 = 199.8 → 199
      expect(calc.computeTaxCents(999, "FR")).toBe(199);
    });

    it("returns 0 for zero taxable", () => {
      expect(calc.computeTaxCents(0, "US")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(calc.computeTaxCents(-500, "US")).toBe(0);
    });

    it("uses 0 as default rate when not specified", () => {
      const noDefault = new RegionalTaxCalculator({ "US": 0.1 });
      expect(noDefault.computeTaxCents(1000, "DE")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns tax for valid rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 10% of 1000 = 100
    expect(await calc.computeTaxCents(1000, "US")).toBe(100);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("floors fractional cents", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8.75% of 1001 = 87.5875 → 87
    expect(await calc.computeTaxCents(1001, "US-CA")).toBe(87);
  });

  it("returns 0 for zero taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    // provider should not be called when taxable <= 0
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-500, "US")).toBe(0);
  });

  it("throws RangeError for rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("service down")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
      "service down",
    );
  });
});

