      cart.add(makeProduct({ id: "x" }), 3);
      cart.updateQuantity("x", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 3);
      cart.updateQuantity("x", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 1);
      expect(() => cart.updateQuantity("x", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
