toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine, Product } from "../src/product.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

function makeLine(
  product: Partial<Product> = {},
  quantity = 1,
): CartLine {
  return { product: makeProduct(product), quantity };
}

describe("InventoryError", () => {
  it("has the correct shape and name", () => {
    const err = new InventoryError("out of stock", "prod-42", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err).toBeInstanceOf(InventoryError);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-42");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("allows undefined available", () => {
    const err = new InventoryError("gone", "prod-99", 3, undefined);
    expect(err.available).toBeUndefined();
    expect(err.requested).toBe(3);
  });
});

describe("refreshPrices", () => {
  it("updates prices from the fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1500)
        .mockResolvedValueOnce(2500),
    };
    const lines: CartLine[] = [
      makeLine({ id: "a", unitPriceCents: 1000 }, 2),
      makeLine({ id: "b", unitPriceCents: 2000 }, 1),
    ];
    const refreshed = await refreshPrices(lines, fetcher);

    expect(refreshed).toHaveLength(2);
    expect(refreshed[0]!.product.unitPriceCents).toBe(1500);
    expect(refreshed[0]!.quantity).toBe(2);
    expect(refreshed[1]!.product.unitPriceCents).toBe(2500);
    expect(refreshed[1]!.quantity).toBe(1);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("b");
  });

  it("preserves other product fields", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const lines: CartLine[] = [
      makeLine({ id: "x", name: "Gizmo", weightGrams: 250, currency: "EUR" }, 1),
    ];
    const refreshed = await refreshPrices(lines, fetcher);
    expect(refreshed[0]!.product.name).toBe("Gizmo");
    expect(refreshed[0]!.product.weightGrams).toBe(250);
    expect(refreshed[0]!.product.currency).toBe("EUR");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const refreshed = await refreshPrices([], fetcher);
    expect(refreshed).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(
      refreshPrices([makeLine({ id: "bad" })], fetcher),
    ).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(
      refreshPrices([makeLine({ id: "bad" })], fetcher),
    ).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network error")),
    };
    await expect(
      refreshPrices([makeLine()], fetcher),
    ).rejects.toThrow("network error");
  });
});

