import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct(), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding same product again", () => {
      const cart = new Cart();
      const p = makeProduct();
      cart.add(p, 2);
      cart.add(p, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct(), 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct(), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct(), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() =>
        cart.add(makeProduct({ unitPriceCents: -1 }), 1),
      ).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 1);
      expect(cart.remove("x")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity for existing product", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 3);
      cart.updateQuantity("x", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 3);
      cart.updateQuantity("x", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 1);
      expect(() => cart.updateQuantity("x", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "x" }), 1);
      expect(() => cart.updateQuantity("x", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 1);
      cart.add(makeProduct({ id: "b" }), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copies of lines", () => {
      const cart = new Cart();
      const product = makeProduct({ id: "s1" });
      cart.add(product, 2);
      const snap = cart.snapshot();
      // mutate snapshot — should not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals – pricing pipeline", () => {
    it("computes subtotal from lines", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 500 }), 3); // 1500
      cart.add(makeProduct({ id: "b", unitPriceCents: 200 }), 2); // 400
      const t = cart.totals();
      expect(t.subtotalCents).toBe(1900);
    });

    it("returns zero totals for empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t.subtotalCents).toBe(0);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(0);
    });

    it("applies discount, then tax on discounted subtotal, then shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };

      const cart = new Cart({
        discountPolicy,
        taxCalculator,
        shippingCalculator,
        region: "US-CA",
      });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 2); // subtotal 2000

      const t = cart.totals();

      // discount called with subtotal
      expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(2000);
      // tax called with discounted subtotal (2000 - 200 = 1800)
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1800, "US-CA");
      // shipping called with lines and discounted subtotal
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        1800,
      );

      expect(t.subtotalCents).toBe(2000);
      expect(t.discountCents).toBe(200);
      expect(t.taxCents).toBe(80);
      expect(t.shippingCents).toBe(500);
      // total = discountedSubtotal + tax + shipping = 1800 + 80 + 500
      expect(t.totalCents).toBe(2380);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: () => 99999,
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(1000); // clamped to subtotal
      expect(t.totalCents).toBe(0); // all discounted, no tax, no shipping
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const negTax: TaxCalculator = {
        computeTaxCents: () => -100,
      };
      const cart = new Cart({ taxCalculator: negTax });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const negShip: ShippingCalculator = {
        computeShippingCents: () => -200,
      };
      const cart = new Cart({ shippingCalculator: negShip });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("uses default US region", () => {
      const taxCalc: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: taxCalc });
      cart.add(makeProduct(), 1);
      cart.totals();
      expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(
        expect.any(Number),
        "US",
      );
    });
  });

  describe("checkout", () => {
    it("returns totals and lines without collaborators", async () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 500 }), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.product.id).toBe("a");
    });

    describe("price refresh", () => {
      it("refreshes prices before computing totals", async () => {
        const fetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(2000),
        };
        const cart = new Cart();
        cart.add(makeProduct({ id: "x", unitPriceCents: 1000 }), 1);
        const result = await cart.checkout({ priceFetcher: fetcher });
        expect(result.totals.subtotalCents).toBe(2000);
        expect(result.lines[0]!.product.unitPriceCents).toBe(2000);
        expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("x");
      });
    });

    describe("inventory check", () => {
      it("passes when items are available", async () => {
        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true }),
        };
        const cart = new Cart();
        cart.add(makeProduct({ id: "a" }), 2);
        const result = await cart.checkout({ inventoryChecker: checker });
        expect(result.totals.subtotalCents).toBe(2000);
        expect(checker.check).toHaveBeenCalledWith("a", 2);
      });

      it("throws InventoryError when item is unavailable", async () => {
        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: false,
            reason: "out of stock",
          }),
        };
        const cart = new Cart();
        cart.add(makeProduct({ id: "gone" }), 3);

        try {
          await cart.checkout({ inventoryChecker: checker });
          expect.unreachable("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("gone");
          expect(invErr.requested).toBe(3);
          expect(invErr.message).toBe("out of stock");
        }
      });

      it("throws InventoryError for partial-stock denial", async () => {
        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: true,
            availableQuantity: 1,
          }),
        };
        const cart = new Cart();
        cart.add(makeProduct({ id: "low" }), 5);

        try {
          await cart.checkout({ inventoryChecker: checker });
          expect.unreachable("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("low");
          expect(invErr.requested).toBe(5);
          expect(invErr.available).toBe(1);
        }
      });

      it("does not throw when availableQuantity meets requested", async () => {
        const checker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({
            available: true,
            availableQuantity: 5,
          }),
        };
        const cart = new Cart();
        cart.add(makeProduct({ id: "ok" }), 5);
        const result = await cart.checkout({ inventoryChecker: checker });
        expect(result.totals.subtotalCents).toBe(5000);
      });
    });

    describe("async tax provider", () => {
      it("uses async tax provider to compute tax", async () => {
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.1),
        };
        const cart = new Cart({ region: "US" });
        cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
        const result = await cart.checkout({ asyncTaxProvider });
        // 10% of 1000 = 100
        expect(result.totals.taxCents).toBe(100);
        expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
      });

      it("applies discount before async tax calculation", async () => {
        const discountPolicy: DiscountPolicy = {
          computeDiscountCents: () => 200,
        };
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.1),
        };
        const cart = new Cart({ discountPolicy, region: "FR" });
        cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
        const result = await cart.checkout({ asyncTaxProvider });
        // discounted subtotal = 1000 - 200 = 800, tax = 10% of 800 = 80
        expect(result.totals.discountCents).toBe(200);
        expect(result.totals.taxCents).toBe(80);
      });

      it("propagates async tax provider failure", async () => {
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
        };
        const cart = new Cart();
        cart.add(makeProduct(), 1);
        await expect(
          cart.checkout({ asyncTaxProvider }),
        ).rejects.toThrow("tax service down");
      });
    });

    describe("full pipeline with all collaborators", () => {
      it("refreshes prices, checks inventory, applies async tax", async () => {
        const discountPolicy: DiscountPolicy = {
          computeDiscountCents: () => 100,
        };
        const shippingCalculator: ShippingCalculator = {
          computeShippingCents: () => 500,
        };
        const priceFetcher: PriceFetcher = {
          fetchPriceCents: vi.fn().mockResolvedValue(800),
        };
        const inventoryChecker: InventoryChecker = {
          check: vi.fn().mockResolvedValue({ available: true }),
        };
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn().mockResolvedValue(0.05),
        };

        const cart = new Cart({ discountPolicy, shippingCalculator });
        cart.add(makeProduct({ id: "item1" }), 2);

        const result = await cart.checkout({
          priceFetcher,
          inventoryChecker,
          asyncTaxProvider,
        });

        // refreshed price: 800 * 2 = 1600 subtotal
        expect(result.totals.subtotalCents).toBe(1600);
        // discount: 100
        expect(result.totals.discountCents).toBe(100);
        // discounted subtotal: 1500, tax: 5% of 1500 = 75
        expect(result.totals.taxCents).toBe(75);
        // shipping: 500
        expect(result.totals.shippingCents).toBe(500);
        // total: 1500 + 75 + 500 = 2075
        expect(result.totals.totalCents).toBe(2075);

        expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("item1");
        expect(inventoryChecker.check).toHaveBeenCalledWith("item1", 2);
      });
    });
  });
});

